//! Authoritative mutation records at fixed node homes. Physical posting placement
//! is a field in the record; it does not determine how the record is located.
use super::persistence::block_on_for_sync_writer;
use super::super::{topology_access::{NodeRecord,Kind,Binding},topology_visibility::Visibility};
use anyhow::{ensure,Result};
use chroma_blockstore::{provider::BlockfileProvider,arrow::provider::BlockfileReaderOptions,BlockfileWriterOptions};
use parking_lot::{Mutex,MutexGuard};
use std::{cell::RefCell,collections::{BTreeMap,BTreeSet,VecDeque},sync::{Arc,Weak,atomic::{AtomicU64,Ordering}}};
use uuid::Uuid;
struct Elapsed<'a>{counter:&'a AtomicU64,start:std::time::Instant}
impl Drop for Elapsed<'_>{fn drop(&mut self){self.counter.fetch_add(self.start.elapsed().as_nanos().min(u64::MAX as u128)as u64,Ordering::Relaxed);}}
#[derive(Clone,Debug)]pub struct Record{pub node:NodeRecord,pub centroid_code:Vec<u8>,pub posting_owner:usize,pub posting_epoch:u64,pub revision:u64}
impl Record{pub fn payload_bytes(&self)->usize{self.node.payload_bytes()+self.centroid_code.len()+64}}
#[derive(Clone,Copy)]pub struct Limits{pub cache_entries:usize,pub cache_bytes:usize,pub record_bytes:usize,pub pin_bytes:usize,pub dirty_records:usize,pub dirty_bytes:usize}
impl Default for Limits{fn default()->Self{Self{cache_entries:8,cache_bytes:32*1024,record_bytes:8*1024,pin_bytes:1024*1024,dirty_records:256,dirty_bytes:4*1024*1024}}}
#[derive(Clone)]struct Change{revision:u64,value:Option<Arc<Record>>}
struct State{roots:Vec<Option<Uuid>>,dirty:BTreeMap<u32,Change>,dirty_bytes:usize,reserved:usize}
#[derive(Default)]struct Cache{values:BTreeMap<(Uuid,u32),Arc<Record>>,order:VecDeque<(Uuid,u32)>,bytes:usize,peak:usize,evictions:u64}
thread_local!{static CREDITS:RefCell<BTreeMap<usize,Vec<Weak<Mutex<usize>>>>>=RefCell::new(BTreeMap::new());static MUTABLE:RefCell<BTreeSet<usize>>=RefCell::new(BTreeSet::new());}
pub struct Store{provider:BlockfileProvider,pub visibility:Arc<Visibility>,pub limits:Limits,dim:usize,state:Mutex<State>,cache:Mutex<Cache>,flush_gate:Mutex<()>,stripes:Vec<Mutex<()>>,pins:Mutex<(usize,usize)>,revisions:AtomicU64,reads:AtomicU64,commits:AtomicU64,fetch_nanos:AtomicU64,flush_nanos:AtomicU64,flush_wait_nanos:AtomicU64,flush_calls:AtomicU64}
pub struct ReadLease<'a>{store:&'a Store,pub(super) record:Arc<Record>,bytes:usize}
impl Drop for ReadLease<'_>{fn drop(&mut self){self.store.pins.lock().0-=self.bytes;}}
pub struct WriteLease<'a>{store:&'a Store,_credit:Option<Reservation<'a>>,_guard:MutexGuard<'a,()>,pub draft:Record,bytes:usize,done:bool}
impl Drop for WriteLease<'_>{fn drop(&mut self){self.store.pins.lock().0-=self.bytes;MUTABLE.with(|v|{v.borrow_mut().remove(&(self.store as *const _ as usize));});if !self.done && std::thread::panicking(){self.store.visibility.poison();}}}
impl WriteLease<'_>{pub(super) fn delete(mut self)->Result<()>{self.store.delete(self.draft.node.id)?;self.done=true;Ok(())}pub fn commit(mut self)->Result<()>{let empty=Record{node:NodeRecord{id:self.draft.node.id,parent:None,centroid:vec![],kind:Kind::Leaf{physical_rows:0},binding:self.draft.node.binding},centroid_code:vec![],posting_owner:self.draft.posting_owner,posting_epoch:self.draft.posting_epoch,revision:0};let draft=std::mem::replace(&mut self.draft,empty);self.store.put(draft)?;self.done=true;Ok(())}}
pub struct Reservation<'a>{store:&'a Store,remaining:Arc<Mutex<usize>>,pin_bytes:usize}
impl Drop for Reservation<'_>{fn drop(&mut self){let mut state=self.store.state.lock();state.reserved-=*self.remaining.lock();self.store.pins.lock().0-=self.pin_bytes;CREDITS.with(|v|{let mut v=v.borrow_mut();if let Some(entries)=v.get_mut(&(self.store as *const _ as usize)){entries.retain(|w|w.as_ptr()!=Arc::as_ptr(&self.remaining));}});}}
impl Store{
 pub fn reserve(&self,records:usize)->Result<Reservation<'_>>{let mut s=self.state.lock();let total=s.dirty.len().checked_add(s.reserved).and_then(|v|v.checked_add(records)).ok_or_else(||anyhow::anyhow!("node reservation overflow"))?;ensure!(total<=self.limits.dirty_records && total.checked_mul(self.limits.record_bytes).is_some_and(|v|v<=self.limits.dirty_bytes),"node transaction headroom before detach");let pin_bytes=records.checked_mul(self.limits.record_bytes).ok_or_else(||anyhow::anyhow!("transaction pin extent"))?;self.pin(pin_bytes)?;s.reserved+=records;let remaining=Arc::new(Mutex::new(records));CREDITS.with(|v|v.borrow_mut().entry(self as *const _ as usize).or_default().push(Arc::downgrade(&remaining)));Ok(Reservation{store:self,remaining,pin_bytes})}
 fn admit_dirty(&self,s:&mut State,id:u32)->Result<()>{if s.dirty.contains_key(&id){return Ok(());}let credit=CREDITS.with(|v|v.borrow().get(&(self as *const _ as usize)).is_some_and(|entries|entries.iter().rev().any(|w|w.upgrade().is_some_and(|c|{let mut c=c.lock();if *c>0{*c-=1;true}else{false}}))));if credit{s.reserved-=1;}else{let total=s.dirty.len().checked_add(s.reserved).and_then(|v|v.checked_add(1)).ok_or_else(||anyhow::anyhow!("node dirty overflow"))?;ensure!(total<=self.limits.dirty_records && total.checked_mul(self.limits.record_bytes).is_some_and(|v|v<=self.limits.dirty_bytes),"dirty node capacity reserved by another transaction");}Ok(())}
 pub fn locator(&self,id:u32)->Result<Option<(usize,u64,bool)>>{let lease=self.read(id)?;Ok(lease.as_ref().map(|v|(v.record.posting_owner,v.record.posting_epoch,matches!(v.record.node.kind,Kind::Leaf{..}))))}
 pub fn new(provider:BlockfileProvider,homes:usize,dim:usize,limits:Limits,visibility:Arc<Visibility>)->Result<Self>{ensure!(homes>0 && homes<=8 && dim>0 && limits.cache_entries>0 && limits.record_bytes>0 && limits.record_bytes<=limits.cache_bytes && limits.pin_bytes>=limits.record_bytes && limits.dirty_records>0 && limits.dirty_bytes>=limits.record_bytes,"node store admission");Ok(Self{provider,visibility,limits,dim,state:Mutex::new(State{roots:vec![None;homes],dirty:BTreeMap::new(),dirty_bytes:0,reserved:0}),cache:Mutex::default(),flush_gate:Mutex::new(()),stripes:(0..64).map(|_|Mutex::new(())).collect(),pins:Mutex::new((0,0)),revisions:AtomicU64::new(0),reads:AtomicU64::new(0),commits:AtomicU64::new(0),fetch_nanos:AtomicU64::new(0),flush_nanos:AtomicU64::new(0),flush_wait_nanos:AtomicU64::new(0),flush_calls:AtomicU64::new(0)})}
 pub fn home(&self,id:u32)->usize{id as usize%self.state.lock().roots.len()}
 fn admit_record(&self,r:&Record)->Result<()>{ensure!(r.centroid_code.len()==chroma_index::quantization::Code::<1>::size(self.dim) && r.node.centroid.len()==self.dim && r.node.centroid.iter().all(|v|v.is_finite()) && r.posting_owner<self.state.lock().roots.len() && r.payload_bytes()<=self.limits.record_bytes,"full node record admission");Ok(())}
 fn pin(&self,bytes:usize)->Result<()>{let mut p=self.pins.lock();ensure!(p.0.checked_add(bytes).is_some_and(|n|n<=self.limits.pin_bytes),"node pin admission");p.0+=bytes;p.1=p.1.max(p.0);Ok(())}
 pub fn read(&self,id:u32)->Result<Option<ReadLease<'_>>>{let Some(record)=self.get(id)?else{return Ok(None);};let bytes=record.payload_bytes().checked_mul(2).ok_or_else(||anyhow::anyhow!("read draft size overflow"))?;self.pin(bytes)?;Ok(Some(ReadLease{store:self,record,bytes}))}
 pub fn write(&self,id:u32)->Result<Option<WriteLease<'_>>>{ensure!(!MUTABLE.with(|v|v.borrow().contains(&(self as *const _ as usize))),"nested mutable node lease must be released before recursion");let guard=self.stripes[id as usize%self.stripes.len()].lock();let Some(record)=self.get(id)?else{return Ok(None);};let has_credit=CREDITS.with(|v|v.borrow().get(&(self as *const _ as usize)).is_some_and(|entries|entries.iter().any(|w|w.upgrade().is_some_and(|c|*c.lock()>0))));let already_dirty={self.state.lock().dirty.contains_key(&id)};let credit=if already_dirty||has_credit{None}else{Some(self.reserve(1)?)};self.pin(self.limits.record_bytes)?;MUTABLE.with(|v|{v.borrow_mut().insert(self as *const _ as usize);});Ok(Some(WriteLease{store:self,_credit:credit,_guard:guard,draft:(*record).clone(),bytes:self.limits.record_bytes,done:false}))}
 fn get(&self,id:u32)->Result<Option<Arc<Record>>>{ensure!(!self.visibility.failed(),"poisoned node store");let root={let s=self.state.lock();if let Some(c)=s.dirty.get(&id){return Ok(c.value.clone());}s.roots[id as usize%s.roots.len()]};let Some(root)=root else{return Ok(None);};self.read_at(root,id)}
 fn read_at(&self,root:Uuid,id:u32)->Result<Option<Arc<Record>>>{let key=(root,id);{let mut c=self.cache.lock();if let Some(v)=c.values.get(&key).cloned(){c.order.retain(|k|*k!=key);c.order.push_back(key);return Ok(Some(v));}}let _elapsed=Elapsed{counter:&self.fetch_nanos,start:std::time::Instant::now()};self.reads.fetch_add(1,Ordering::Relaxed);let result=block_on_for_sync_writer(async{let reader=self.provider.read::<u32,&[u32]>(BlockfileReaderOptions::new(root,String::new())).await.map_err(|e|anyhow::anyhow!("{e}"))?;let value=reader.get("node64",id).await.map_err(|e|anyhow::anyhow!("{e}"))?.map(|v|decode(id,v,self.dim,self.limits.record_bytes)).transpose()?;reader.clear_loaded_blocks();Ok::<_,anyhow::Error>(value)})?;let Some(record)=result else{return Ok(None);};let record=Arc::new(record);let bytes=record.payload_bytes();let mut c=self.cache.lock();if let Some(v)=c.values.get(&key){return Ok(Some(v.clone()));}while c.values.len()>=self.limits.cache_entries || c.bytes+bytes>self.limits.cache_bytes{let old=c.order.pop_front().expect("record fits cache");c.bytes-=c.values.remove(&old).unwrap().payload_bytes();c.evictions+=1;}c.bytes+=bytes;c.peak=c.peak.max(c.bytes);c.order.push_back(key);c.values.insert(key,record.clone());Ok(Some(record))}
 pub fn put(&self,mut r:Record)->Result<()>{self.admit_record(&r)?;ensure!(!self.visibility.failed(),"poisoned node update");let bytes=r.payload_bytes();let mut s=self.state.lock();self.admit_dirty(&mut s,r.node.id)?;let prior=s.dirty.get(&r.node.id).and_then(|c|c.value.as_ref()).map_or(0,|r|r.payload_bytes());ensure!(s.dirty.contains_key(&r.node.id) || s.dirty.len()<self.limits.dirty_records,"dirty node count admission before update");ensure!(s.dirty_bytes-prior+bytes<=self.limits.dirty_bytes,"dirty node byte admission before update");r.revision=self.revisions.fetch_add(1,Ordering::Relaxed).checked_add(1).ok_or_else(||anyhow::anyhow!("node revision exhausted"))?;r.node.binding=Binding::Live{owner:r.posting_owner,epoch:r.revision};let id=r.node.id;let revision=r.revision;s.dirty_bytes=s.dirty_bytes-prior+bytes;s.dirty.insert(id,Change{revision,value:Some(Arc::new(r))});Ok(())}
 pub fn delete(&self,id:u32)->Result<()>{let mut s=self.state.lock();self.admit_dirty(&mut s,id)?;ensure!(s.dirty.contains_key(&id) || s.dirty.len()<self.limits.dirty_records,"node tombstone admission");let prior=s.dirty.get(&id).and_then(|c|c.value.as_ref()).map_or(0,|r|r.payload_bytes());s.dirty_bytes-=prior;let revision=self.revisions.fetch_add(1,Ordering::Relaxed)+1;s.dirty.insert(id,Change{revision,value:None});Ok(())}
 /// Dirty records and the prior complete root tuple remain authoritative until
 /// every changed home flushes. Newer concurrent drafts are never acknowledged.
 pub fn flush(&self)->Result<Vec<Option<Uuid>>>{let _elapsed=Elapsed{counter:&self.flush_nanos,start:std::time::Instant::now()};self.flush_calls.fetch_add(1,Ordering::Relaxed);let wait=std::time::Instant::now();let _gate=self.flush_gate.lock();self.flush_wait_nanos.fetch_add(wait.elapsed().as_nanos().min(u64::MAX as u128)as u64,Ordering::Relaxed);let(roots,changes)={let s=self.state.lock();(s.roots.clone(),s.dirty.clone())};if changes.is_empty(){return Ok(roots);}let result=block_on_for_sync_writer(async{let mut next=roots.clone();for home in 0..roots.len(){let rows:Vec<_>=changes.iter().filter(|(id,_)|**id as usize%roots.len()==home).collect();if rows.is_empty(){continue;}let mut options=BlockfileWriterOptions::new(String::new()).ordered_mutations().max_block_size_bytes(16*1024);if let Some(root)=roots[home]{options=options.fork(root);}let w=self.provider.write::<u32,Vec<u32>>(options).await.map_err(|e|anyhow::anyhow!("{e}"))?;for(id,c)in rows{if let Some(r)=&c.value{w.set("node64",*id,encode(r)?).await.map_err(|e|anyhow::anyhow!("{e}"))?;}else{w.delete::<_,Vec<u32>>("node64",*id).await.map_err(|e|anyhow::anyhow!("{e}"))?;}}let f=w.commit::<u32,Vec<u32>>().await.map_err(|e|anyhow::anyhow!("{e}"))?;let id=f.id();f.flush::<u32,Vec<u32>>().await.map_err(|e|anyhow::anyhow!("{e}"))?;next[home]=Some(id);self.commits.fetch_add(1,Ordering::Relaxed);}Ok::<_,anyhow::Error>(next)});let roots=match result{Ok(v)=>v,Err(e)=>{self.visibility.poison();return Err(e);}};let mut s=self.state.lock();s.roots=roots.clone();for(id,c)in changes{if s.dirty.get(&id).is_some_and(|v|v.revision==c.revision){if let Some(r)=s.dirty.remove(&id).unwrap().value{s.dirty_bytes-=r.payload_bytes();}}}Ok(roots)}
 pub fn report(&self)->serde_json::Value{let s=self.state.lock();let c=self.cache.lock();let p=self.pins.lock();serde_json::json!({"policy":"fixed-home-full-mutation-records-v1","homes":s.roots.len(),"cache_entries":c.values.len(),"cache_bytes":c.bytes,"peak_cache_bytes":c.peak,"cache_entry_cap":self.limits.cache_entries,"cache_byte_cap":self.limits.cache_bytes,"dirty_records":s.dirty.len(),"reserved_dirty_records":s.reserved,"dirty_bytes":s.dirty_bytes,"active_pin_bytes":p.0,"peak_pin_bytes":p.1,"pin_cap":self.limits.pin_bytes,"point_reads":self.reads.load(Ordering::Relaxed),"home_commits":self.commits.load(Ordering::Relaxed),"point_miss_elapsed_ns":self.fetch_nanos.load(Ordering::Relaxed),"flush_call_elapsed_ns":self.flush_nanos.load(Ordering::Relaxed),"flush_gate_wait_ns":self.flush_wait_nanos.load(Ordering::Relaxed),"flush_calls":self.flush_calls.load(Ordering::Relaxed),"timer_scope":"Cumulative elapsed spans include failed attempts. Point miss covers provider open/get/decode/cache admission after a clean-cache miss. Flush covers gate wait/snapshot/writes/flush/ack, including no-op calls. Gate wait is nested; concurrent spans overlap and are not CPU or disjoint wall buckets.","evictions":c.evictions,"scope":"Admitted clean records, read/draft/wave pins, held transaction payload and dirty payload only; post-decode admission, encoded/root/provider/allocator buffers and RSS are separate. Fixed node homes locate both kinds; posting owner is mutable metadata."})}
}
fn encode(r:&Record)->Result<Vec<u32>>{let(kind,count,children)=match &r.node.kind{Kind::Leaf{physical_rows}=>(0,u32::try_from(*physical_rows)?,&[][..]),Kind::Internal{children}=>(1,u32::try_from(children.len())?,children.as_slice())};let mut w=vec![0x4e4f4432,2,r.node.parent.unwrap_or(u32::MAX),kind,count,r.node.centroid.len()as u32,r.centroid_code.len()as u32,r.posting_owner as u32,r.posting_epoch as u32,(r.posting_epoch>>32)as u32,r.revision as u32,(r.revision>>32)as u32];w.extend(r.node.centroid.iter().map(|v|v.to_bits()));w.extend(children);for bytes in r.centroid_code.chunks(4){let mut a=[0;4];a[..bytes.len()].copy_from_slice(bytes);w.push(u32::from_le_bytes(a));}Ok(w)}
fn decode(id:u32,w:&[u32],dim:usize,cap:usize)->Result<Record>{ensure!(w.len()>=12 && w[0]==0x4e4f4432 && w[1]==2 && w[5]as usize==dim && w[3]<=1,"full node header");let children=if w[3]==1{w[4]as usize}else{0};let code=w[6]as usize;ensure!(code==chroma_index::quantization::Code::<1>::size(dim),"full node centroid code extent");let payload=dim.checked_mul(4).and_then(|v|v.checked_add(children.checked_mul(4)?)).and_then(|v|v.checked_add(code)).and_then(|v|v.checked_add(64)).ok_or_else(||anyhow::anyhow!("full node extent overflow"))?;ensure!(payload<=cap && 12usize.checked_add(dim).and_then(|v|v.checked_add(children)).and_then(|v|v.checked_add(code.div_ceil(4)))==Some(w.len()),"full node extent");let centroid:Vec<_>=w[12..12+dim].iter().map(|v|f32::from_bits(*v)).collect();ensure!(centroid.iter().all(|v|v.is_finite()),"full node finite centroid");let revision=u64::from(w[10])|(u64::from(w[11])<<32);let posting_epoch=u64::from(w[8])|(u64::from(w[9])<<32);let mut centroid_code=Vec::with_capacity(code);for word in &w[12+dim+children..]{centroid_code.extend(word.to_le_bytes());}ensure!(centroid_code[code..].iter().all(|v|*v==0),"full node padding");centroid_code.truncate(code);Ok(Record{node:NodeRecord{id,parent:(w[2]!=u32::MAX).then_some(w[2]),centroid,kind:if w[3]==0{Kind::Leaf{physical_rows:w[4]as usize}}else{Kind::Internal{children:w[12+dim..12+dim+children].to_vec()}},binding:Binding::Live{owner:w[7]as usize,epoch:revision}},centroid_code,posting_owner:w[7]as usize,posting_epoch,revision})}
#[cfg(test)]mod tests{
 use super::*;use chroma_blockstore::arrow::provider::ArrowBlockfileProvider;use chroma_cache::new_cache_for_test;use chroma_storage::{local::LocalStorage,Storage};use chroma_index::quantization::Code;
 fn provider(path:&std::path::Path)->BlockfileProvider{BlockfileProvider::ArrowBlockfileProvider(ArrowBlockfileProvider::new(Storage::Local(LocalStorage::new(path.to_str().unwrap())),16*1024,new_cache_for_test(),new_cache_for_test(),2))}
 fn record(id:u32,internal:bool)->Record{let centroid=vec![id as f32,-0.];Record{node:NodeRecord{id,parent:None,centroid:centroid.clone(),kind:if internal{Kind::Internal{children:vec![0,2]}}else{Kind::Leaf{physical_rows:4}},binding:Binding::Live{owner:0,epoch:0}},centroid_code:Code::<1>::quantize(&centroid,&[0.;2]).as_ref().to_vec(),posting_owner:0,posting_epoch:0,revision:0}}
 #[tokio::test(flavor="multi_thread",worker_threads=2)]async fn full_node_store_fixed_home_eviction_lease_and_old_roots(){let dir=tempfile::tempdir().unwrap();let view=Arc::new(Visibility::default());let s=Store::new(provider(dir.path()),2,2,Limits{cache_entries:1,cache_bytes:256,record_bytes:256,pin_bytes:512,dirty_records:4,dirty_bytes:1024},view.clone()).unwrap();for id in 0..4{s.put(record(id,id==1)).unwrap();}let old=s.flush().unwrap();assert_eq!(s.home(0),0);assert_eq!(s.home(1),1);for id in 0..4{let r=s.read(id).unwrap().unwrap();assert_eq!(r.record.node.id,id);assert_eq!(r.record.centroid_code,record(id,id==1).centroid_code);}let original=s.read_at(old[0].unwrap(),0).unwrap().unwrap();{let mut lease=s.write(0).unwrap().unwrap();lease.draft.posting_owner=1;lease.draft.posting_epoch=1;lease.draft.node.parent=Some(1);lease.commit().unwrap();}let next=s.flush().unwrap();{let lease=s.write(0).unwrap().unwrap();assert!(s.write(64).is_err(),"colliding nested mutable request rejects before waiting");lease.commit().unwrap();}assert_ne!(old[0],next[0]);assert_eq!(s.home(0),0);let current=s.read(0).unwrap().unwrap();assert_eq!(current.record.posting_owner,1);assert_eq!(current.record.posting_epoch,1);assert_eq!(current.record.node.parent,Some(1));assert_eq!(s.read_at(old[0].unwrap(),0).unwrap().unwrap().posting_owner,original.posting_owner);assert!(s.report()["evictions"].as_u64().unwrap()>0);drop(current);assert_eq!(s.report()["active_pin_bytes"],0);println!("FULL_NODE_CORE {}",s.report());}
 #[tokio::test(flavor="multi_thread",worker_threads=2)]async fn full_node_reservation_excludes_competing_dirty_work(){let dir=tempfile::tempdir().unwrap();let s=Store::new(provider(dir.path()),2,2,Limits{cache_entries:1,cache_bytes:256,record_bytes:256,pin_bytes:512,dirty_records:2,dirty_bytes:512},Arc::new(Visibility::default())).unwrap();let held=s.reserve(2).unwrap();std::thread::scope(|scope|{assert!(scope.spawn(||s.put(record(99,false))).join().unwrap().is_err());});assert!(s.get(99).unwrap().is_none());s.put(record(0,false)).unwrap();s.put(record(1,false)).unwrap();assert_eq!(s.report()["reserved_dirty_records"],0);drop(held);s.flush().unwrap();assert!(s.get(0).unwrap().is_some());assert!(s.get(1).unwrap().is_some());println!("NODE_RESERVATION competing update rejects before publication; holder consumes two reserved slots");}
 #[test]fn full_node_codec_rejects_wrong_format_extent_padding(){let r=record(9,true);let words=encode(&r).unwrap();let decoded=decode(9,&words,2,256).unwrap();assert_eq!(decoded.node.centroid.iter().map(|v|v.to_bits()).collect::<Vec<_>>(),r.node.centroid.iter().map(|v|v.to_bits()).collect::<Vec<_>>());assert_eq!(decoded.centroid_code,r.centroid_code);for edit in 0..4{let mut bad=words.clone();match edit{0=>bad[0]=0x544f5031,1=>bad[6]=u32::MAX,2=>{bad.pop();},_=>bad[12]=f32::NAN.to_bits()};assert!(decode(9,&bad,2,256).is_err());}assert!(decode(9,&words,2,64).is_err());}
}

// The compatibility enum keeps ordinary reference guards unchanged. Owner
// records move their payload into one admitted draft rather than a graph mirror.
use super::super::common::{TreeNode,LeafNode,InternalNode,VectorKey};
use std::ops::{Deref,DerefMut};
pub enum NodeRead<'a,I:VectorKey>{Legacy(dashmap::mapref::one::Ref<'a,u32,TreeNode<I>>),Owner{_pin:ReadLease<'a>,value:TreeNode<I>}}
impl<I:VectorKey> NodeRead<'_,I>{pub fn value(&self)->&TreeNode<I>{self}}
impl<I:VectorKey> Deref for NodeRead<'_,I>{type Target=TreeNode<I>;fn deref(&self)->&Self::Target{match self{Self::Legacy(v)=>v.value(),Self::Owner{value,..}=>value}}}
pub enum NodeWrite<'a,I:VectorKey>{Legacy(dashmap::mapref::one::RefMut<'a,u32,TreeNode<I>>),Owner{lease:Option<WriteLease<'a>>,value:Option<TreeNode<I>>}}
impl<I:VectorKey> NodeWrite<'_,I>{pub fn key(&self)->&u32{match self{Self::Legacy(v)=>v.key(),Self::Owner{lease,..}=>&lease.as_ref().unwrap().draft.node.id}}pub fn value(&self)->&TreeNode<I>{self}pub fn value_mut(&mut self)->&mut TreeNode<I>{self}}
impl<I:VectorKey> Deref for NodeWrite<'_,I>{type Target=TreeNode<I>;fn deref(&self)->&Self::Target{match self{Self::Legacy(v)=>v.value(),Self::Owner{value,..}=>value.as_ref().unwrap()}}}
impl<I:VectorKey> DerefMut for NodeWrite<'_,I>{fn deref_mut(&mut self)->&mut Self::Target{match self{Self::Legacy(v)=>v.value_mut(),Self::Owner{value,..}=>value.as_mut().unwrap()}}}
impl<I:VectorKey> Drop for NodeWrite<'_,I>{fn drop(&mut self){if let Self::Owner{lease,value}=self{let Some(mut lease)=lease.take()else{return;};if std::thread::panicking(){lease.store.visibility.poison();return;}update_record(&mut lease.draft,value.take().unwrap());let store=lease.store;if let Err(error)=lease.commit(){store.visibility.poison();panic!("node draft commit failed: {error}");}}}}
pub fn tree<I:VectorKey>(r:&Record)->TreeNode<I>{match &r.node.kind{Kind::Leaf{physical_rows}=>TreeNode::Leaf(LeafNode{centroid:r.node.centroid.clone(),centroid_code:r.centroid_code.clone(),parent_id:r.node.parent,length:*physical_rows,ids:vec![],versions:vec![],codes:vec![]}),Kind::Internal{children}=>TreeNode::Internal(InternalNode{centroid:r.node.centroid.clone(),centroid_code:r.centroid_code.clone(),parent_id:r.node.parent,children:children.clone()})}}
pub(super) fn take_tree<I:VectorKey>(r:&mut Record)->TreeNode<I>{let centroid=std::mem::take(&mut r.node.centroid);let centroid_code=std::mem::take(&mut r.centroid_code);match &mut r.node.kind{Kind::Leaf{physical_rows}=>TreeNode::Leaf(LeafNode{centroid,centroid_code,parent_id:r.node.parent,length:*physical_rows,ids:vec![],versions:vec![],codes:vec![]}),Kind::Internal{children}=>TreeNode::Internal(InternalNode{centroid,centroid_code,parent_id:r.node.parent,children:std::mem::take(children)})}}
fn update_record<I:VectorKey>(r:&mut Record,node:TreeNode<I>){match node{TreeNode::Leaf(v)=>{assert!(v.ids.is_empty() && v.codes.is_empty() && v.versions.is_empty(),"owner node record cannot mirror posting rows");r.node.parent=v.parent_id;r.node.centroid=v.centroid;r.centroid_code=v.centroid_code;r.node.kind=Kind::Leaf{physical_rows:v.length};},TreeNode::Internal(v)=>{r.node.parent=v.parent_id;r.node.centroid=v.centroid;r.centroid_code=v.centroid_code;r.node.kind=Kind::Internal{children:v.children};}}}
pub fn from_tree<I:VectorKey>(id:u32,node:TreeNode<I>,posting_owner:usize,posting_epoch:u64)->Record{let mut r=Record{node:NodeRecord{id,parent:None,centroid:vec![],kind:Kind::Leaf{physical_rows:0},binding:Binding::Live{owner:posting_owner,epoch:0}},centroid_code:vec![],posting_owner,posting_epoch,revision:0};update_record(&mut r,node);r}
impl<I:VectorKey> super::HierarchicalSpannWriter<I>{
 pub(super) fn node_get(&self,id:&u32)->Option<NodeRead<'_,I>>{if let Some(store)=&self.node_store{store.read(*id).expect("authoritative node read").map(|pin|{let value=tree(&pin.record);NodeRead::Owner{_pin:pin,value}})}else{self.nodes.get(id).map(NodeRead::Legacy)}}
 pub(super) fn node_mut(&self,id:&u32)->Option<NodeWrite<'_,I>>{if let Some(store)=&self.node_store{store.write(*id).expect("authoritative node write").map(|mut lease|{let value=take_tree(&mut lease.draft);NodeWrite::Owner{lease:Some(lease),value:Some(value)}})}else{self.nodes.get_mut(id).map(NodeWrite::Legacy)}}
 pub(super) fn node_exists(&self,id:&u32)->bool{if let Some(store)=&self.node_store{store.locator(*id).expect("authoritative node existence").is_some()}else{self.nodes.contains_key(id)}}
}

struct WavePins<'a>{store:&'a Store,bytes:usize}
impl Drop for WavePins<'_>{fn drop(&mut self){self.store.pins.lock().0-=self.bytes;}}
struct FullAccess<'a,I:VectorKey>{kernel:&'a super::HierarchicalSpannWriter<I>,store:&'a Store,_pins:WavePins<'a>}
impl<I:VectorKey> super::super::topology_access::NodeAccess for FullAccess<'_,I>{
 fn wave_rows(&self)->usize{8}
 fn require_complete(&self)->bool{true}
 fn expected_missing(&self,kind:usize,id:u32)->bool{let view=self.kernel.topology_visibility.as_ref().unwrap();let allowed=view.permits_missing(kind,id);if allowed{view.expected_missing();}allowed}
 fn missing_record(&self,kind:usize,_id:u32){self.kernel.topology_visibility.as_ref().unwrap().missing(kind);}
 fn fetch(&self,ids:&[u32])->Result<Vec<Option<Arc<NodeRecord>>>>{ensure!(ids.len()<=8,"full node wave admission");ids.iter().map(|id|Ok(self.store.get(*id)?.map(|v|Arc::new(v.node.clone())))).collect()}
}
impl<I:VectorKey> super::HierarchicalSpannWriter<I>{
 pub(super) fn navigate_full_records(&self,query:&[f32],policy:&super::super::common::ReadBeamPolicy)->Result<(Vec<(u32,f32)>,super::super::topology_access::NavigationWork)>{let store=self.node_store.as_ref().unwrap();let bytes=store.limits.record_bytes.checked_mul(16).ok_or_else(||anyhow::anyhow!("wave pin extent"))?;store.pin(bytes)?;let access=FullAccess{kernel:self,store,_pins:WavePins{store,bytes}};super::super::topology_access::navigate(&access,self.root_id(),&self.distance_fn,query,policy)}
}
